What does this code print to the serial monitor when it runs?

```
const float K = 0.2, TAU = 0.1, THETA = 0.05, TAUC = 0.05;
const float KC = (1.0 / K) * TAU / (TAUC + THETA);
const float TI = min(TAU, 4.0 * (TAUC + THETA));

void setup() {
  Serial.begin(9600);
  Serial.print("Kc=");
  Serial.print(KC, 1);
  Serial.print(" Ti=");
  Serial.println(TI, 2);
}
void loop() {}
```

